#!/bin/bash
# Resumable: skips any elite whose master exists. Each elite has its own design and invented palette.
D="$(cd "$(dirname "$0")" && pwd)"
run() { [ -f "$D/masters/$1.png" ] || "$D/run.sh" "$1" "$2" > "$D/masters/$1.log" 2>&1; }
run anvil_cloud "ANVIL CLOUD, a flying lightning-siege artillery barge with a flat-topped anvil crossbeam over a tapering hull and one big shell cannon pointing up the screen. Materials: heavy bone-ivory ceramic armour plates (aged, hairline-cracked, soot-streaked at the seams) over a black forged-iron frame; riveted brass bands and a brass recoil collar on the cannon; the cannon bore is a deep barrel whose mouth glows small and white-gold; the anvil shoulders carry black iron capacitor blocks with copper-gold contacts; flat vents on the stern; stern engines in blackened steel. Palette: ivory, black iron, brass-gold, a little white-gold glow. Keep the flat T-shaped anvil read."
run refinery_tender "REFINERY TENDER, a flying fuel-tanker hauler: a wide barrel hull of two big cylindrical tanks side by side around a central canister cradle, outer pipe racks, drop hatch, twin hauler engines at the stern. Materials: enamelled deep emerald-green tanks (chipped, oil-stained, welded ring seams), bare galvanised zinc pipes and racks, brass valve wheels and gauges, pale cream canister caps and plates, riveted black-iron collars, small amber lamps. Palette: emerald enamel, zinc, brass, cream. Make the pipe racks and cradle clearly separate readable parts."
run rod_dancer "ROD DANCER, a slim flying skirmisher with two long separated lightning rods rising forward like a tuning fork, a central cockpit spine, delta stabilisers and split aft thrusters. Materials: glossy carbon-black composite hull with fine panel lines; royal-blue anodised metal on the delta stabilisers and spine plates; the two rods are polished chrome tubes with segmented insulator rings and little glass coil windings, each tipped by a small turquoise-white arc node; a thin braided cable arc between the rods and the cockpit; small turquoise glass cockpit. Palette: carbon black, royal blue, chrome, turquoise-white. Keep the slim tall silhouette."
run skyhook_harrier "SKYHOOK HARRIER, a swept-wing hooked interceptor with a long grappling lance and barbed hook at the nose, a cable winch amidships and two aft engines. Materials: graphite-steel wings and fuselage with sun-bleached safety-orange paint on the wing leading edges, nose cone and winch housing (worn, chipped, showing bare metal under it); the hook and lance are black forged steel with polished edges; the winch cable is braided steel with an orange pull-ring; small white-blue sensor lights; engine cowls in dark steel. Palette: graphite, safety orange, black steel, a little white-blue. Orange only on structural leading edges and the winch, never banded."
run static_bastion "STATIC BASTION, a wide flying shield-tank with four capacitor spires, overlapping segmented shield plates and a central ward core, heavy engine bank of four thrusters. Materials: deep petrol-teal enamelled armour plates (scuffed, with lighter teal edge-wear) layered like shields over a dark steel chassis; silver-white polished shield facets on the outer plates; four spires of white ceramic insulator discs on steel posts topped with small pale ice-cyan arc nodes; the central ward core is a glass lens in a silver ring glowing pale ice-cyan; bolted black-steel engine housings. Palette: petrol teal, silver, ceramic white, pale ice-cyan. Keep the wide shield-tank silhouette."
echo done > "$D/masters/ALL_DONE"
